const B64 = {}; [...'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'].forEach((c, i) => { B64[c] = i; });
function decode(sec) { // VLQ state carries across lines; keep only wanted lines
  const str = sec.map.mappings, vals = [];
  let line = 0, col = 0, src = 0, ol = 0, oc = 0, nm = 0, cur = sec.want.has(0) ? [] : null;
